UPDATE users
SET last_login_at = #{lastLoginAt}
WHERE id = #{id}

UPDATE users
SET password_hash = #{passwordHash}
WHERE id = #{id}
  AND deleted_at IS NULL

UPDATE users
SET payment_password_hash = #{paymentPasswordHash}
WHERE id = #{id}
  AND deleted_at IS NULL

UPDATE users
SET avatar_url = #{avatarUrl}
WHERE id = #{id}
  AND deleted_at IS NULL
